  function qrStyleIcon(shape='square',eye='square'){
   // Miniature QR with three finder eyes and a fixed data pattern.
   let cells='';
   const module=(x,y)=>shape==='dots'?'<circle cx="'+(x+.5)+'" cy="'+(y+.5)+'" r=".43"/>':'<rect x="'+x+'" y="'+y+'" width="1" height="1" rx="'+(shape==='rounded'?.28:0)+'"/>';
   for(let y=0;y<21;y++)for(let x=0;x<21;x++){if((x<8&&y<8)||(x>12&&y<8)||(x<8&&y>12))continue;if((x*3+y*5+x*y)%7<3)cells+=module(x+2,y+2);}
   for(const [x,y] of [[2,2],[16,2],[2,16]]){
    if(eye==='circle')cells+='<circle cx="'+(x+3.5)+'" cy="'+(y+3.5)+'" r="3" fill="none" stroke="currentColor" stroke-width="1"/><circle cx="'+(x+3.5)+'" cy="'+(y+3.5)+'" r="1.5"/>';
    else cells+='<rect x="'+(x+.5)+'" y="'+(y+.5)+'" width="6" height="6" rx="'+(eye==='rounded'?1.6:0)+'" fill="none" stroke="currentColor"/><rect x="'+(x+2)+'" y="'+(y+2)+'" width="3" height="3" rx="'+(eye==='rounded'?.7:0)+'"/>';
   }
   return '<svg viewBox="0 0 25 25" fill="currentColor" aria-hidden="true">'+cells+'</svg>';
  }
